record User(String name, int age, String department) {}

List<User> users = List.of(
    new User("Avi", 30, "Engineering"),
    new User("Dana", 25, "Product"),
    new User("Noa", 17, "Engineering")
);

List<String> adultNames = new ArrayList<>();

for (User user : users) {
    if (user.age() >= 18) {
        adultNames.add(user.name());
    }
}

